const json = (body, status = 200) => Response.json(body, {status, headers: {'Cache-Control':'no-store'}});
async function api(request, env) {
  const user = request.headers.get('oai-authenticated-user-id');
  if (!user) return json({error:'Sign in required'}, 401);
  if (!env.DB) return json({error:'Storage unavailable'}, 503);
  if (request.method === 'GET') {
    const row = await env.DB.prepare('SELECT payload, revision FROM itineraries WHERE id = ?').bind(user).first();
    return json({tripData: row ? JSON.parse(row.payload) : null, revision: row?.revision || 0});
  }
  if (request.method !== 'PUT') return json({error:'Method not allowed'}, 405);
  if (request.headers.get('Origin') !== new URL(request.url).origin) return json({error:'Invalid origin'}, 403);
  const body = await request.text();
  if (body.length > 100000) return json({error:'Too large'}, 413);
  let data;
  try { data = JSON.parse(body); } catch { return json({error:'Invalid JSON'}, 400); }
  if (!Number.isSafeInteger(data.revision) || data.revision < 0 || !data.tripData) return json({error:'Invalid data'}, 400);
  const clean = {};
  for (const day of ['day1','day2','day3']) {
    const value = data.tripData[day];
    const ids = Array.isArray(value) ? value : value?.ids;
    const notes = Array.isArray(value) ? {} : value?.notes;
    if (!Array.isArray(ids) || ids.length > 100 || ids.some(id => typeof id !== 'string' || id.length > 100) || !notes || typeof notes !== 'object' || Array.isArray(notes)) return json({error:'Invalid schedule'}, 400);
    const safeNotes = Object.create(null);
    for (const id of ids) {
      if (notes[id] !== undefined && (typeof notes[id] !== 'string' || notes[id].length > 5000)) return json({error:'Invalid note'}, 400);
      if (notes[id] !== undefined) safeNotes[id] = notes[id];
    }
    clean[day] = {ids: [...new Set(ids)], notes:safeNotes};
  }
  const payload = JSON.stringify(clean);
  const result = data.revision === 0
    ? await env.DB.prepare('INSERT INTO itineraries (id,payload,revision) VALUES (?,?,1) ON CONFLICT(id) DO NOTHING').bind(user,payload).run()
    : await env.DB.prepare('UPDATE itineraries SET payload = ?, revision = revision + 1 WHERE id = ? AND revision = ?').bind(payload,user,data.revision).run();
  if (!result.meta.changes) return json({error:'Conflict'}, 409);
  return json({revision:data.revision + 1});
}

const html = "<!DOCTYPE html>\r\n<html lang=\"zh-TW\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>宜蘭行程規劃</title>\r\n    <!-- Tailwind CSS CDN -->\r\n    <script src=\"https://cdn.tailwindcss.com\"></script>\r\n    <!-- FontAwesome for Icons -->\r\n    <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\">\r\n    <!-- Inter Font -->\r\n    <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Noto+Sans+TC:wght@400;500;700&display=swap\" rel=\"stylesheet\">\r\n    <style>\r\n        body {\r\n            font-family: 'Noto Sans TC', 'Inter', sans-serif;\r\n            font-size: 1.1rem; /* 文字放大 10% */\r\n        }\r\n        .custom-shadow {\r\n            box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.03), 0 8px 10px -6px rgba(0, 0, 0, 0.03);\r\n        }\r\n    </style>\r\n</head>\r\n<body class=\"bg-slate-50 text-slate-700 min-h-screen flex flex-col\">\r\n\r\n    <!-- 頂部導航列：改為單一清新水藍色（無漸層） -->\r\n    <header class=\"bg-[#0284c7] text-slate-50 shadow-sm sticky top-0 z-50\">\r\n        <div class=\"max-w-7xl mx-auto px-4 py-3 sm:py-4 flex flex-col sm:flex-row justify-between items-center gap-3\">\r\n            <div class=\"flex items-center space-x-3\">\r\n                <div class=\"bg-white/15 p-2.5 rounded-xl backdrop-blur-sm\">\r\n                    <i class=\"fa-solid fa-map-location-dot text-2xl text-sky-100\"></i>\r\n                </div>\r\n                <div>\r\n                    <h2 class=\"text-lg sm:text-2xl font-bold tracking-tight\">宜蘭行程規劃</h2>\r\n                    <p class=\"text-xs sm:text-sm text-sky-100 opacity-90\">三日行程自由排・雲端自動同步</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"flex items-center gap-2\">\r\n                <!-- 雲端同步狀態指示器 -->\r\n                <div id=\"cloud-sync-status\" class=\"bg-black/20 border border-white/10 text-sky-100 text-sm px-3.5 py-1.5 rounded-full flex items-center gap-1.5\">\r\n                    <i class=\"fa-solid fa-cloud text-sky-200 animate-pulse\"></i>\r\n                    <span id=\"sync-text\">連線雲端中...</span>\r\n                </div>\r\n                <span id=\"completed-counter\" class=\"bg-black/20 text-sm px-3.5 py-1.5 rounded-full border border-white/10 hidden sm:flex items-center gap-1.5 text-sky-100\">\r\n                    <i class=\"fa-solid fa-circle-check text-sky-200\"></i> 總站數 <span id=\"total-count\">12</span> 站\r\n                </span>\r\n                <button id=\"reset-schedules\" disabled hidden onclick=\"resetAllSchedules()\" class=\"bg-white/10 hover:bg-white/20 text-sm px-3.5 py-2 rounded-lg transition border border-white/20 flex items-center gap-1\">\r\n                    <i class=\"fa-solid fa-rotate-right\"></i> 重置行程\r\n                </button>\r\n            </div>\r\n        </div>\r\n    </header>\r\n\r\n    <!-- 主要內容區：採用左右排版 -->\r\n    <main class=\"max-w-7xl mx-auto px-4 py-6 w-full grid grid-cols-1 lg:grid-cols-12 gap-6 flex-grow\">\r\n\r\n        <!-- 左側：三日行程規劃表 (5欄) -->\r\n        <div class=\"lg:col-span-5 space-y-6\">\r\n            \r\n            <!-- 防呆小幫手區塊 -->\r\n            <div class=\"bg-white border border-slate-200 rounded-2xl p-4 shadow-xs\">\r\n                <div class=\"flex items-center gap-2 mb-2\">\r\n                    <div class=\"bg-amber-500 text-white p-1.5 rounded-lg text-sm\">\r\n                        <i class=\"fa-solid fa-triangle-exclamation\"></i>\r\n                    </div>\r\n                    <h2 class=\"font-bold text-slate-800 text-base\">重要提醒與防呆</h2>\r\n                </div>\r\n                <p class=\"text-sm text-slate-600 leading-relaxed\">\r\n                    <strong>裡海咖啡</strong>已預約 <span class=\"underline font-bold\">2026/12/14 11:30 (2位)</span>，建議排入 12/14 午餐時段！點擊右側項目的按鈕即可自由編排至 12/12、12/13 或 12/14。\r\n                </p>\r\n            </div>\r\n\r\n            <!-- 日期分頁切換與行程容器 -->\r\n            <div class=\"bg-white rounded-2xl p-5 shadow-xs border border-slate-200 flex flex-col h-[780px]\">\r\n                <div class=\"flex justify-between items-center mb-4\">\r\n                    <h3 class=\"font-bold text-slate-800 flex items-center gap-2 text-lg\">\r\n                        <i class=\"fa-solid fa-calendar-days text-[#0284c7]\"></i> 我的旅遊行程表\r\n                    </h3>\r\n                    <!-- 三日日期 Tab 按鈕 -->\r\n                    <div class=\"flex bg-slate-100 p-1 rounded-xl gap-1\">\r\n                        <button onclick=\"switchDay('day1')\" id=\"tab-day1\" class=\"px-3.5 py-2 rounded-lg text-sm font-bold transition bg-[#0284c7] text-white shadow-xs\">\r\n                            12/12 (五)\r\n                        </button>\r\n                        <button onclick=\"switchDay('day2')\" id=\"tab-day2\" class=\"px-3.5 py-2 rounded-lg text-sm font-bold transition text-slate-500 hover:text-slate-800\">\r\n                            12/13 (六)\r\n                        </button>\r\n                        <button onclick=\"switchDay('day3')\" id=\"tab-day3\" class=\"px-3.5 py-2 rounded-lg text-sm font-bold transition text-slate-500 hover:text-slate-800\">\r\n                            12/14 (日)\r\n                        </button>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- 當前日期標題與說明 -->\r\n                <div class=\"bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 mb-4 flex justify-between items-center\">\r\n                    <div>\r\n                        <span id=\"current-day-title\" class=\"text-sm font-bold text-slate-800\">12月12日 (星期五) 行程</span>\r\n                        <p id=\"current-day-count\" class=\"text-xs text-slate-500\">已排入 0 個站點</p>\r\n                    </div>\r\n                    <button id=\"edit-itinerary\" type=\"button\" onclick=\"toggleItineraryEdit()\" aria-pressed=\"false\" class=\"text-sm bg-[#0284c7] hover:bg-[#0369a1] text-white px-4 py-2 rounded-lg font-medium transition shrink-0\">\r\n                        <i class=\"fa-solid fa-pen mr-1.5\" aria-hidden=\"true\"></i> 編輯\r\n                    </button>\r\n                </div>\r\n\r\n                <!-- 行程站點清單 -->\r\n                <div id=\"itinerary-list\" class=\"space-y-3 overflow-y-auto flex-grow pr-1 custom-scrollbar\">\r\n                    <!-- 動態載入 -->\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- 右側：可用景點與美食資料庫 (7欄) -->\r\n        <div class=\"lg:col-span-7 space-y-6\">\r\n            \r\n            <div class=\"flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 bg-white p-4 rounded-2xl shadow-xs border border-slate-200\">\r\n                <!-- 搜尋列 -->\r\n                <div class=\"relative flex-grow w-full sm:w-auto\">\r\n                    <i class=\"fa-solid fa-magnifying-glass absolute left-3.5 top-3.5 text-slate-400 text-sm\"></i>\r\n                    <input type=\"text\" id=\"search-input\" oninput=\"searchItems()\" placeholder=\"搜尋景點、美食或地區...\" class=\"w-full pl-10 pr-4 py-2.5 bg-slate-50 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-[#0284c7] text-sm\">\r\n                </div>\r\n\r\n                <!-- 分類篩選 -->\r\n                <div class=\"flex gap-1.5 shrink-0 w-full sm:w-auto\">\r\n                    <button onclick=\"filterItems('all')\" id=\"filter-all\" class=\"filter-btn bg-[#0284c7] text-white text-sm px-4 py-2.5 rounded-xl font-medium transition shadow-xs\">全部</button>\r\n                    <button onclick=\"filterItems('attraction')\" id=\"filter-attraction\" class=\"filter-btn bg-slate-100 hover:bg-slate-200 text-slate-600 text-sm px-4 py-2.5 rounded-xl font-medium transition\">景點</button>\r\n                    <button onclick=\"filterItems('restaurant')\" id=\"filter-restaurant\" class=\"filter-btn bg-slate-100 hover:bg-slate-200 text-slate-600 text-sm px-4 py-2.5 rounded-xl font-medium transition\">美食</button>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- 清單容器 -->\r\n            <div id=\"items-container\" class=\"space-y-4 max-h-[740px] overflow-y-auto pr-1\">\r\n                <!-- 動態載入項目 -->\r\n            </div>\r\n        </div>\r\n\r\n    </main>\r\n\r\n    <!-- 頁尾 -->\r\n    <footer class=\"bg-slate-800 text-slate-300 py-6 text-center text-sm mt-12 border-t border-slate-700\">\r\n        <div class=\"max-w-7xl mx-auto px-4 space-y-1\">\r\n            <p>宜蘭旅遊行程規劃小幫手 © 2026 | 三日行程自由編排系統</p>\r\n            <p class=\"text-slate-400 text-xs\">點擊項目上的加入按鈕即可配置到 12/12、12/13 或 12/14 行程表中！</p>\r\n        </div>\r\n    </footer>\r\n\r\n    <!-- JavaScript 邏輯 -->\r\n    <script type=\"module\">\r\n\r\n\r\n\r\n\r\n        let isCloudSynced = false;\r\n        let cloudRevision = 0, pendingSave = false, saving = false, syncReady = false, syncConflict = false;\r\n\r\n        // 資料庫：包含景點與餐廳\r\n        const items = [\r\n            {\r\n                id: 'spot-1',\r\n                type: 'attraction',\r\n                name: '猴洞坑瀑布',\r\n                location: '宜蘭縣礁溪鄉白石腳路',\r\n                tag: '礁溪鄉',\r\n                desc: '步道輕鬆好走（約10分鐘即可抵達瀑布上方），免門票、無須預約。上方有小水池與戲水區，登高可眺望蘭陽平原美景。',\r\n                mapUrl: 'https://www.google.com/maps/place/?q=place_id:ChIJO_MKTSH6ZzQRc62tjx_IfU8'\r\n            },\r\n            {\r\n                id: 'rest-1',\r\n                type: 'restaurant',\r\n                name: '里海咖啡',\r\n                location: '宜蘭縣礁溪鄉玉龍路二段406號',\r\n                tag: '礁溪鄉',\r\n                highlight: '已訂位：2026/12/14 11:30 (2位)',\r\n                desc: '<strong>營業時間：</strong>週一至週日 11:30 – 20:30（每週三、週四固定公休）<br><strong>網友推薦：</strong>產地直送的鮮魚定食料理與精緻咖啡，魚貨品質極高，空間高質感，為礁溪極具人氣的私房愛店。',\r\n                mapUrl: 'https://www.google.com/maps/place/?q=place_id:ChIJfZ16wkz6ZzQRCweZrN2ohpE'\r\n            },\r\n            {\r\n                id: 'rest-2',\r\n                type: 'restaurant',\r\n                name: '立早餐',\r\n                location: '宜蘭縣羅東鎮康莊路',\r\n                tag: '羅東鎮',\r\n                desc: '<strong>營業時間：</strong>週一至週日 06:00 – 13:00（無特定公休，依店家公告為主）<br><strong>網友推薦：</strong>手工粉漿蛋餅外皮微酥軟Q（推薦南瓜鹹蛋口味）、自家製蘿蔔糕、自製抹醬厚片與總匯吐司套餐。',\r\n                mapUrl: 'https://www.google.com/maps/place/?q=place_id:ChIJRaVftKvnZzQRJJ9JjDsleq8'\r\n            },\r\n            {\r\n                id: 'rest-3',\r\n                type: 'restaurant',\r\n                name: '食壱拉麵-鴨蔥拉麵',\r\n                location: '宜蘭縣羅東鎮民生路',\r\n                tag: '羅東鎮',\r\n                desc: '<strong>營業時間：</strong>週一至週日 11:30 – 14:00, 17:00 – 20:30（每週三、週四固定公休）<br><strong>網友推薦：</strong>湯頭濃郁清甜帶有蔥香，鴨肉軟嫩不柴，是羅東高評價且少見的特色鴨蔥拉麵。',\r\n                mapUrl: 'https://www.google.com/maps/place/?q=place_id:ChIJiffuE5PnZzQR_NDwWWDwH5Q'\r\n            },\r\n            {\r\n                id: 'rest-4',\r\n                type: 'restaurant',\r\n                name: '張秀雄米苔目',\r\n                location: '宜蘭縣羅東鎮天津路5-9號',\r\n                tag: '羅東鎮',\r\n                desc: '<strong>營業時間：</strong>週一至週日 05:30 – 12:30（每週二固定公休）<br><strong>網友推薦：</strong>豬大骨熬製清甜湯頭搭配滑溜Q彈米苔目，黑白切小菜與宜蘭特有粉腸（沾特製辣椒醬）為必點招牌。',\r\n                mapUrl: 'https://www.google.com/maps/place/?q=place_id:ChIJEyAeon7mZzQR0wcDqegV5Ls'\r\n            },\r\n            {\r\n                id: 'rest-5',\r\n                type: 'restaurant',\r\n                name: '珍藏早餐（原水如意早餐）',\r\n                location: '宜蘭縣羅東鎮大同路',\r\n                tag: '羅東鎮',\r\n                desc: '<strong>營業時間：</strong>週一至週日 05:30 – 11:30（每週三固定公休）<br><strong>網友推薦：</strong>手工現做三星蔥蛋餅，皮薄嫩帶Ｑ度，搭配滿滿三星蔥與自製蒜蓉辣椒醬，蔥香濃郁。',\r\n                mapUrl: 'https://www.google.com/maps/place/?q=place_id:ChIJXTH-3XjmZzQR4jPem-80k_A'\r\n            },\r\n            {\r\n                id: 'spot-2',\r\n                type: 'attraction',\r\n                name: '宜蘭農夫青蔥體驗農場',\r\n                location: '宜蘭縣三星鄉安農南路二段',\r\n                tag: '三星鄉',\r\n                desc: '熱門在地農村體驗景點（Google 4.5星）。提供專業導覽、拔蔥、洗蔥以及手作蔥油餅體驗，非常適合親子同遊。',\r\n                mapUrl: 'https://www.google.com/maps/place/?q=place_id:ChIJ-0m4FazhZzQRPZphfINz_cg'\r\n            },\r\n            {\r\n                id: 'spot-3',\r\n                type: 'attraction',\r\n                name: '三星地區農會',\r\n                location: '宜蘭縣三星鄉中山路二段',\r\n                tag: '三星鄉',\r\n                desc: '鄰近三星鄉中心，為推廣在地農業的重要機構，周邊常可採買到著名的三星蔥、上將梨等農特產品資訊。',\r\n                mapUrl: 'https://www.google.com/maps/place/?q=place_id:ChIJBejZa7XhZzQR7HjIRacP270'\r\n            },\r\n            {\r\n                id: 'spot-4',\r\n                type: 'attraction',\r\n                name: '大鯖魚夢工廠',\r\n                location: '宜蘭縣蘇澳鎮大圳路',\r\n                tag: '蘇澳鎮',\r\n                desc: '結合在地鯖魚文化的觀光工廠。館內展示豐富鯖魚知識、提供特色鯖魚料理餐點與多樣化伴手禮，環境寬敞舒適。',\r\n                mapUrl: 'https://www.google.com/maps/place/?q=place_id:ChIJHYobiaHpZzQRJ-WUexwBCY4'\r\n            },\r\n            {\r\n                id: 'spot-5',\r\n                type: 'attraction',\r\n                name: '拳頭姆自然步道',\r\n                location: '宜蘭縣三星鄉台7丙線9.5公里處',\r\n                tag: '三星鄉',\r\n                desc: '步道全長約 1.3 公里，坡度平緩好走。沿途為美麗烏心石造林地與豐富蕨類生態，設有觀景平台可眺望蘭陽平原。',\r\n                mapUrl: 'https://www.google.com/maps/place/?q=place_id:ChIJVfHJCJcKaDQR8y1rWQdanwU'\r\n            },\r\n            {\r\n                id: 'spot-6',\r\n                type: 'attraction',\r\n                name: '清水地熱公園',\r\n                location: '宜蘭縣大同鄉清水路82-1號',\r\n                tag: '大同鄉',\r\n                desc: '<strong>營業時間：</strong>週一至週日 09:00 – 17:00<br>超人氣溫泉煮食與免費泡腳樂園。可租借竹籠煮玉米、雞蛋，並享受足湯樂趣。',\r\n                mapUrl: 'https://www.google.com/maps/place/?q=place_id:ChIJuX8uLwMaZzQRd0B_n_n_n_c'\r\n            }\r\n        ];\r\n\r\n        let currentDay = 'day1'; // 'day1', 'day2' 或 'day3'\r\n        let currentFilter = 'all';\r\n        let isEditing = false;\r\n        let tripData = {\r\n            day1: { ids: [], notes: {} },\r\n            day2: { ids: [], notes: {} },\r\n            day3: { ids: [], notes: {} }\r\n        };\r\n\r\n        // 初始化 Firebase 與身分驗證\r\n\r\n        function updateSyncStatus(text, color = 'text-sky-200', icon = 'fa-cloud') {\r\n            const el = document.getElementById('cloud-sync-status');\r\n            if (el) el.innerHTML = `<i class=\"fa-solid ${icon} ${color}\"></i> <span>${text}</span>`;\r\n        }\r\n        async function fetchCloud() {\r\n            const r = await fetch('/api/itinerary', { cache: 'no-store' });\r\n            if (!r.ok) throw Error('Cloud unavailable');\r\n            return r.json();\r\n        }\r\n        async function initFirebase() {\r\n            try {\r\n                const data = await fetchCloud();\r\n                cloudRevision = data.revision;\r\n                if (data.tripData) tripData = data.tripData;\r\n                else {\r\n                    loadFromLocalStorage();\r\n                    pendingSave = Object.values(tripData).some(day => (day.ids || day).length);\r\n                }\r\n                isCloudSynced = syncReady = true;\r\n                renderAll();\r\n                if (pendingSave) await saveCloudData();\r\n                else updateSyncStatus('\\u96f2\\u7aef\\u5df2\\u540c\\u6b65', 'text-emerald-300');\r\n            } catch {\r\n                updateSyncStatus('\\u9023\\u7dda\\u5931\\u6557\\uff0c\\u8acb\\u91cd\\u65b0\\u6574\\u7406', 'text-rose-300');\r\n                renderAll();\r\n            }\r\n        }\r\n        async function saveCloudData() {\r\n            pendingSave = true;\r\n            saveToLocalStorage();\r\n            if (saving || syncConflict || !syncReady) return;\r\n            saving = true;\r\n            try {\r\n                while (pendingSave) {\r\n                    pendingSave = false;\r\n                    updateSyncStatus('\\u5132\\u5b58\\u4e2d\\u2026');\r\n                    const r = await fetch('/api/itinerary', {method: 'PUT', headers: {'Content-Type':'application/json'}, body: JSON.stringify({tripData, revision:cloudRevision})});\r\n                    if (r.status === 409) { syncConflict = true; throw Error('Conflict'); }\r\n                    if (!r.ok) throw Error('Save failed');\r\n                    cloudRevision = (await r.json()).revision;\r\n                }\r\n                updateSyncStatus('\\u96f2\\u7aef\\u5df2\\u540c\\u6b65', 'text-emerald-300');\r\n            } catch {\r\n                pendingSave = true;\r\n                updateSyncStatus(syncConflict ? '\\u7248\\u672c\\u885d\\u7a81\\uff0c\\u8acb\\u91cd\\u65b0\\u6574\\u7406' : '\\u5c1a\\u672a\\u540c\\u6b65\\uff0c\\u9023\\u7dda\\u5f8c\\u81ea\\u52d5\\u91cd\\u8a66', 'text-rose-300');\r\n            } finally { saving = false; }\r\n        }\r\n        setInterval(async () => {\r\n            if (!syncReady || saving || syncConflict) return;\r\n            if (pendingSave) { saveCloudData(); return; }\r\n            if (isEditing || document.hidden) return;\r\n            try {\r\n                const data = await fetchCloud();\r\n                if (pendingSave || saving || isEditing) return;\r\n                if (data.revision !== cloudRevision) {\r\n                    cloudRevision = data.revision;\r\n                    if (data.tripData) tripData = data.tripData;\r\n                    renderAll();\r\n                }\r\n                updateSyncStatus('\\u96f2\\u7aef\\u5df2\\u540c\\u6b65', 'text-emerald-300');\r\n            } catch { updateSyncStatus('\\u9023\\u7dda\\u4e2d\\u65b7\\uff0c\\u6b63\\u5728\\u91cd\\u8a66', 'text-amber-300'); }\r\n        }, 5000);\r\n        window.addEventListener('beforeunload', event => {\r\n            if (pendingSave || saving) { event.preventDefault(); event.returnValue = ''; }\r\n        });\r\n\r\n        function saveToLocalStorage() {\r\n            localStorage.setItem('yilan_schedule_day1', JSON.stringify(tripData.day1));\r\n            localStorage.setItem('yilan_schedule_day2', JSON.stringify(tripData.day2));\r\n            localStorage.setItem('yilan_schedule_day3', JSON.stringify(tripData.day3));\r\n        }\r\n\r\n        function loadFromLocalStorage() {\r\n            const d1 = localStorage.getItem('yilan_schedule_day1');\r\n            const d2 = localStorage.getItem('yilan_schedule_day2');\r\n            const d3 = localStorage.getItem('yilan_schedule_day3');\r\n            if (d1) tripData.day1 = JSON.parse(d1);\r\n            if (d2) tripData.day2 = JSON.parse(d2);\r\n            if (d3) tripData.day3 = JSON.parse(d3);\r\n        }\r\n\r\n\r\n        function renderAll() {\r\n            const editButton = document.getElementById('edit-itinerary');\r\n            editButton.disabled = !syncReady || syncConflict;\r\n            editButton.setAttribute('aria-pressed', String(isEditing));\r\n            editButton.innerHTML = isEditing\r\n                ? '<i class=\"fa-solid fa-check mr-1.5\" aria-hidden=\"true\"></i> 完成'\r\n                : '<i class=\"fa-solid fa-pen mr-1.5\" aria-hidden=\"true\"></i> 編輯';\r\n            const resetButton = document.getElementById('reset-schedules');\r\n            resetButton.disabled = !isEditing;\r\n            resetButton.hidden = !isEditing;\r\n            resetButton.classList.toggle('hidden', !isEditing);\r\n            renderItinerary();\r\n            applyFilterAndSearch();\r\n            const totalCount = items.length;\r\n            const countEl = document.getElementById('total-count');\r\n            if (countEl) countEl.innerText = totalCount;\r\n        }\r\n\r\n        // 搜尋與篩選整合處理\r\n        function searchItems() {\r\n            applyFilterAndSearch();\r\n        }\r\n\r\n        function applyFilterAndSearch() {\r\n            const searchInput = document.getElementById('search-input');\r\n            const keyword = searchInput ? searchInput.value.trim().toLowerCase() : '';\r\n\r\n            let filtered = items.filter(item => {\r\n                const matchesType = (currentFilter === 'all') || (item.type === currentFilter);\r\n                const matchesKeyword = !keyword || \r\n                    item.name.toLowerCase().includes(keyword) || \r\n                    item.location.toLowerCase().includes(keyword) || \r\n                    item.tag.toLowerCase().includes(keyword) || \r\n                    item.desc.toLowerCase().includes(keyword);\r\n                return matchesType && matchesKeyword;\r\n            });\r\n\r\n            renderItems(filtered);\r\n        }\r\n\r\n        // 切換日期分頁\r\n        function switchDay(day) {\r\n            currentDay = day;\r\n            const btn1 = document.getElementById('tab-day1');\r\n            const btn2 = document.getElementById('tab-day2');\r\n            const btn3 = document.getElementById('tab-day3');\r\n            const title = document.getElementById('current-day-title');\r\n\r\n            if (!btn1 || !btn2 || !btn3) return;\r\n\r\n            btn1.className = \"px-3 py-1.5 rounded-lg text-xs font-bold transition text-slate-500 hover:text-slate-800\";\r\n            btn2.className = \"px-3 py-1.5 rounded-lg text-xs font-bold transition text-slate-500 hover:text-slate-800\";\r\n            btn3.className = \"px-3 py-1.5 rounded-lg text-xs font-bold transition text-slate-500 hover:text-slate-800\";\r\n\r\n            if (day === 'day1') {\r\n                btn1.className = \"px-3 py-1.5 rounded-lg text-xs font-bold transition bg-[#0284c7] text-white shadow-sm\";\r\n                title.innerText = \"12月12日 (星期五) 行程\";\r\n            } else if (day === 'day2') {\r\n                btn2.className = \"px-3 py-1.5 rounded-lg text-xs font-bold transition bg-[#0284c7] text-white shadow-sm\";\r\n                title.innerText = \"12/13 (星期六) 行程\";\r\n            } else {\r\n                btn3.className = \"px-3 py-1.5 rounded-lg text-xs font-bold transition bg-[#0284c7] text-white shadow-sm\";\r\n                title.innerText = \"12/14 (星期日) 行程\";\r\n            }\r\n            renderItinerary();\r\n        }\r\n\r\n        function toggleItineraryEdit() {\r\n            if (!syncReady || syncConflict) return;\r\n            isEditing = !isEditing;\r\n            renderAll();\r\n        }\r\n\r\n        function getSchedule(day) {\r\n            const val = tripData[day];\r\n            if (Array.isArray(val)) {\r\n                return { ids: val, notes: {} };\r\n            }\r\n            return val || { ids: [], notes: {} };\r\n        }\r\n\r\n        function updateSchedule(day, newIds, newNotes) {\r\n            if (!isEditing || !syncReady || syncConflict) return;\r\n            tripData[day] = { ids: newIds, notes: newNotes };\r\n            if (isCloudSynced) {\r\n                saveCloudData();\r\n            } else {\r\n                saveToLocalStorage();\r\n            }\r\n            renderAll();\r\n        }\r\n\r\n        // 將項目加入指定日期\r\n        function addToSchedule(itemId, day) {\r\n            if (!isEditing || !syncReady || syncConflict) return;\r\n            let dayObj = getSchedule(day);\r\n            let ids = [...dayObj.ids];\r\n            let notes = { ...dayObj.notes };\r\n            if (!ids.includes(itemId)) {\r\n                ids.push(itemId);\r\n                updateSchedule(day, ids, notes);\r\n            }\r\n        }\r\n\r\n        // 從行程中移除\r\n        function removeFromSchedule(itemId, day) {\r\n            if (!isEditing || !syncReady || syncConflict) return;\r\n            let dayObj = getSchedule(day);\r\n            let ids = dayObj.ids.filter(id => id !== itemId);\r\n            let notes = { ...dayObj.notes };\r\n            delete notes[itemId];\r\n            updateSchedule(day, ids, notes);\r\n        }\r\n\r\n        // 更新項目備註\r\n        function updateItemNote(itemId, day, noteText) {\r\n            if (!isEditing || !syncReady || syncConflict) return;\r\n            let dayObj = getSchedule(day);\r\n            let ids = [...dayObj.ids];\r\n            let notes = { ...dayObj.notes, [itemId]: noteText };\r\n            tripData[day] = { ids, notes };\r\n            saveCloudData();\r\n        }\r\n\r\n        // 行程上下移動排序\r\n        function moveItem(index, direction, day) {\r\n            if (!isEditing || !syncReady || syncConflict) return;\r\n            let dayObj = getSchedule(day);\r\n            let ids = [...dayObj.ids];\r\n            let notes = { ...dayObj.notes };\r\n            \r\n            const targetIndex = index + direction;\r\n            if (targetIndex < 0 || targetIndex >= ids.length) return;\r\n            \r\n            const temp = ids[index];\r\n            ids[index] = ids[targetIndex];\r\n            ids[targetIndex] = temp;\r\n            \r\n            updateSchedule(day, ids, notes);\r\n        }\r\n\r\n        // 重置所有行程\r\n        function resetAllSchedules() {\r\n            if (!isEditing || !syncReady || syncConflict) return;\r\n            tripData.day1 = { ids: [], notes: {} };\r\n            tripData.day2 = { ids: [], notes: {} };\r\n            tripData.day3 = { ids: [], notes: {} };\r\n            if (isCloudSynced) {\r\n                saveCloudData();\r\n            } else {\r\n                saveToLocalStorage();\r\n            }\r\n            renderAll();\r\n        }\r\n\r\n        // 渲染左側行程表\r\n        function renderItinerary() {\r\n            const container = document.getElementById('itinerary-list');\r\n            const dayObj = getSchedule(currentDay);\r\n            const scheduleIds = dayObj.ids;\r\n            const notes = dayObj.notes || {};\r\n\r\n            if (!container) return;\r\n            container.innerHTML = '';\r\n\r\n            const countText = document.getElementById('current-day-count');\r\n            if (countText) countText.innerText = `已排入 ${scheduleIds.length} 個站點`;\r\n\r\n            if (scheduleIds.length === 0) {\r\n                container.innerHTML = `\r\n                    <div class=\"bg-slate-50 border border-dashed border-slate-200 rounded-2xl p-8 text-center text-slate-400\">\r\n                        <i class=\"fa-solid fa-calendar-plus text-3xl mb-2 text-slate-300\"></i>\r\n                        <p class=\"text-sm\">此日尚無行程，請從右側點擊加入此日行程！</p>\r\n                    </div>\r\n                `;\r\n                return;\r\n            }\r\n\r\n            scheduleIds.forEach((id, index) => {\r\n                const item = items.find(i => i.id === id);\r\n                if (!item) return;\r\n                const isRestaurant = item.type === 'restaurant';\r\n                const currentNote = notes[id] || '';\r\n\r\n                const card = document.createElement('div');\r\n                card.className = \"bg-white/80 hover:bg-white border border-slate-200/80 rounded-xl p-4 transition flex flex-col gap-2.5 shadow-xs\";\r\n                \r\n                card.innerHTML = `\r\n                    <div class=\"flex items-start justify-between gap-3\">\r\n                        <div class=\"flex items-start gap-3\">\r\n                            <div class=\"bg-[#0284c7] text-white font-bold text-sm w-7 h-7 rounded-lg flex items-center justify-center shrink-0 mt-0.5 shadow-xs\">\r\n                                ${index + 1}\r\n                            </div>\r\n                            <div>\r\n                                <div class=\"flex items-center gap-2 mb-1\">\r\n                                    <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full ${isRestaurant ? 'bg-orange-50 text-orange-700 border border-orange-200' : 'bg-sky-50 text-sky-800'}\">\r\n                                        ${isRestaurant ? '美食' : '景點'}\r\n                                    </span>\r\n                                    <span class=\"text-xs text-slate-500 font-medium\">${item.tag}</span>\r\n                                </div>\r\n                                <h4 class=\"text-base font-bold text-slate-800\">${item.name}</h4>\r\n                                ${item.highlight ? `<p class=\"text-xs text-rose-600 font-bold mt-1 bg-rose-50 px-2.5 py-1 rounded-md border border-rose-200 w-fit\"><i class=\"fa-solid fa-clock mr-1\"></i>${item.highlight}</p>` : ''}\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"${isEditing ? 'flex' : 'hidden'} items-center gap-1 shrink-0\">\r\n                            <div class=\"flex flex-col gap-0.5\">\r\n                                <button onclick=\"moveItem(${index}, -1, '${currentDay}')\" ${index === 0 ? 'disabled class=\"text-slate-300 cursor-not-allowed text-sm p-1\"' : 'class=\"text-slate-400 hover:text-[#0284c7] text-sm p-1 transition\"'} title=\"往上移\">\r\n                                    <i class=\"fa-solid fa-chevron-up\"></i>\r\n                                </button>\r\n                                <button onclick=\"moveItem(${index}, 1, '${currentDay}')\" ${index === scheduleIds.length - 1 ? 'disabled class=\"text-slate-300 cursor-not-allowed text-sm p-1\"' : 'class=\"text-slate-400 hover:text-[#0284c7] text-sm p-1 transition\"'} title=\"往下移\">\r\n                                    <i class=\"fa-solid fa-chevron-down\"></i>\r\n                                </button>\r\n                            </div>\r\n                            <button onclick=\"removeFromSchedule('${id}', '${currentDay}')\" class=\"text-slate-400 hover:text-rose-500 p-1.5 transition text-sm\" title=\"從此日移除\">\r\n                                <i class=\"fa-solid fa-trash-can\"></i>\r\n                            </button>\r\n                        </div>\r\n                    </div>\r\n                    <!-- 即時備註輸入框 -->\r\n                    <div class=\"mt-1\">\r\n                        <input ${isEditing ? '' : 'readonly'} type=\"text\" value=\"${currentNote.replace(/&/g, '&amp;').replace(/\"/g, '&quot;').replace(/</g, '&lt;')}\" oninput=\"updateItemNote('${id}', '${currentDay}', this.value)\" placeholder=\"輸入自訂備註（例如：11:30 抵達、預約保留中）...\" class=\"w-full text-xs px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:outline-none focus:ring-1 focus:ring-[#0284c7] text-slate-600\">\r\n                    </div>\r\n                `;\r\n                container.appendChild(card);\r\n            });\r\n        }\r\n\r\n        // 渲染右側可用景點列表\r\n        function renderItems(dataToRender) {\r\n            const container = document.getElementById('items-container');\r\n            if (!container) return;\r\n            container.innerHTML = '';\r\n\r\n            if (dataToRender.length === 0) {\r\n                container.innerHTML = `\r\n                    <div class=\"bg-white rounded-2xl p-8 text-center text-slate-400 shadow-xs border border-slate-200\">\r\n                        <i class=\"fa-solid fa-face-meh text-3xl mb-2 text-slate-300\"></i>\r\n                        <p class=\"text-sm\">沒有找到符合條件的項目</p>\r\n                    </div>\r\n                `;\r\n                return;\r\n            }\r\n\r\n            dataToRender.forEach(item => {\r\n                const isRestaurant = item.type === 'restaurant';\r\n                const inDay1 = getSchedule('day1').ids.includes(item.id);\r\n                const inDay2 = getSchedule('day2').ids.includes(item.id);\r\n                const inDay3 = getSchedule('day3').ids.includes(item.id);\r\n\r\n                const card = document.createElement('div');\r\n                card.className = \"bg-white rounded-2xl p-5 shadow-xs border border-slate-200 hover:border-[#0284c7] transition duration-200\";\r\n                \r\n                card.innerHTML = `\r\n                    <div class=\"flex items-start justify-between gap-4\">\r\n                        <div class=\"space-y-2\">\r\n                            <div class=\"flex flex-wrap items-center gap-2\">\r\n                                <span class=\"text-xs font-semibold px-3 py-1 rounded-full ${isRestaurant ? 'bg-orange-50 text-orange-700 border border-orange-200' : 'bg-sky-50 text-sky-700 border border-sky-200'}\">\r\n                                    ${isRestaurant ? '<i class=\"fa-solid fa-utensils mr-1\"></i>餐廳美食' : '<i class=\"fa-solid fa-camera mr-1\"></i>觀光景點'}\r\n                                </span>\r\n                                <span class=\"text-xs bg-slate-100 text-slate-600 px-2.5 py-1 rounded-md font-medium\"><i class=\"fa-solid fa-location-dot text-[#0284c7] mr-1\"></i>${item.tag}</span>\r\n                            </div>\r\n                            <h3 class=\"text-lg font-bold text-slate-800\">${item.name}</h3>\r\n                            <p class=\"text-sm text-slate-500\"><i class=\"fa-regular fa-map mr-1\"></i>${item.location}</p>\r\n                            \r\n                            ${item.highlight ? `<div class=\"bg-rose-50 border border-rose-200 text-rose-600 text-xs font-bold px-3 py-1.5 rounded-lg flex items-center gap-1.5 w-fit\"><i class=\"fa-solid fa-calendar-check text-rose-500\"></i>${item.highlight}</div>` : ''}\r\n                            \r\n                            <div class=\"text-sm text-slate-600 leading-relaxed bg-slate-50 p-3 rounded-xl border border-slate-100\">\r\n                                ${item.desc}\r\n                            </div>\r\n                        </div>\r\n\r\n                        <div class=\"flex flex-col items-end gap-2 shrink-0\">\r\n                            <a href=\"${item.mapUrl}\" target=\"_blank\" class=\"bg-slate-100 hover:bg-slate-200 text-slate-700 text-xs px-3 py-2 rounded-xl font-medium transition flex items-center gap-1 border border-slate-200\">\r\n                                <i class=\"fa-solid fa-diamond-turn-right text-slate-500\"></i> 地圖\r\n                            </a>\r\n                            \r\n                            <!-- 三日加入行程按鈕 -->\r\n                            <div class=\"flex flex-col gap-1.5 mt-1\">\r\n                                <button onclick=\"addToSchedule('${item.id}', 'day1')\" ${(!isEditing || inDay1) ? 'disabled class=\"bg-slate-100 text-slate-400 cursor-default text-xs px-3 py-1.5 rounded-lg font-medium\"' : 'class=\"bg-[#0284c7] hover:bg-[#0369a1] text-white text-xs px-3.5 py-1.5 rounded-lg transition font-medium shadow-xs\"'}>\r\n                                    ${inDay1 ? '<i class=\"fa-solid fa-check mr-1\"></i>已在 12/12' : '+ 12/12'}\r\n                                </button>\r\n                                <button onclick=\"addToSchedule('${item.id}', 'day2')\" ${(!isEditing || inDay2) ? 'disabled class=\"bg-slate-100 text-slate-400 cursor-default text-xs px-3 py-1.5 rounded-lg font-medium\"' : 'class=\"bg-[#0284c7] hover:bg-[#0369a1] text-white text-xs px-3.5 py-1.5 rounded-lg transition font-medium shadow-xs\"'}>\r\n                                    ${inDay2 ? '<i class=\"fa-solid fa-check mr-1\"></i>已在 12/13' : '+ 12/13'}\r\n                                </button>\r\n                                <button onclick=\"addToSchedule('${item.id}', 'day3')\" ${(!isEditing || inDay3) ? 'disabled class=\"bg-slate-100 text-slate-400 cursor-default text-xs px-3 py-1.5 rounded-lg font-medium\"' : 'class=\"bg-[#38bdf8] hover:bg-[#0284c7] text-white text-xs px-3.5 py-1.5 rounded-lg transition font-medium shadow-xs\"'}>\r\n                                    ${inDay3 ? '<i class=\"fa-solid fa-check mr-1\"></i>已在 12/14' : '+ 12/14'}\r\n                                </button>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                `;\r\n                container.appendChild(card);\r\n            });\r\n        }\r\n\r\n        function filterItems(type) {\r\n            currentFilter = type;\r\n            document.querySelectorAll('.filter-btn').forEach(btn => {\r\n                btn.className = \"filter-btn bg-slate-100 hover:bg-slate-200 text-slate-600 text-xs px-3 py-2 rounded-xl font-medium transition\";\r\n            });\r\n            const activeBtn = document.getElementById(`filter-${type}`);\r\n            if (activeBtn) {\r\n                activeBtn.className = \"filter-btn bg-[#0284c7] text-white text-xs px-3 py-2 rounded-xl font-medium transition shadow-sm\";\r\n            }\r\n            applyFilterAndSearch();\r\n        }\r\n\r\n        // 綁定全域函式供 HTML onclick 使用\r\n        window.toggleItineraryEdit = toggleItineraryEdit;\r\n        window.switchDay = switchDay;\r\n        window.searchItems = searchItems;\r\n        window.filterItems = filterItems;\r\n        window.addToSchedule = addToSchedule;\r\n        window.removeFromSchedule = removeFromSchedule;\r\n        window.updateItemNote = updateItemNote;\r\n        window.moveItem = moveItem;\r\n        window.resetAllSchedules = resetAllSchedules;\r\n\r\n        // 頁面載入時初始化 Firebase\r\n        window.onload = function() {\r\n            initFirebase();\r\n        };\r\n    </script>\r\n</body>\r\n</html>";
export default {async fetch(request,env) {
  const path = new URL(request.url).pathname;
  try {
    if (path === '/api/itinerary') return await api(request,env);
    if (path === '/' || path === '/index.html') return new Response(html,{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store'}});
    return new Response('Not found',{status:404});
  } catch { return json({error:'Server unavailable'},503); }
}};